-- ── 1. The items must exist ──────────────────────────────────────────────
do $$
declare
  v_missing text;
begin
  select string_agg(w.id, ', ' order by w.id) into v_missing
    from unnest(array['cp2611_cornucopia', 'cp2611_pumpkin_stack', 'cp2611_window_autumn', 'cp2611_poster_gratitude', 'cp2611_leaf_garland', 'cp2611_pillow_plaid', 'cp2611_rug_harvest', 'cp2611_rack_harvest_hall']) as w(id)
   where not exists (select 1 from public.home_items h where h.id = w.id);
  if v_missing is not null then
    raise exception 'Court Pass art can''t be added yet: home_items has no row for %. Apply supabase/migration_court_pass_cycles_2026_11.sql first, then re-run this file.', v_missing;
  end if;
end
$$;

