on conflict (item_id) do update
  set art_svg = excluded.art_svg, updated_at = now()
  where public.home_item_art.art_svg is distinct from excluded.art_svg;

-- ── 3. The aspects ───────────────────────────────────────────────────────
update public.home_items h
   set art_aspect = v.aspect
  from (values
  ('cp2611_cornucopia', 1),
  ('cp2611_pumpkin_stack', 0.75),
  ('cp2611_window_autumn', 0.9),
  ('cp2611_poster_gratitude', 0.8),
  ('cp2611_leaf_garland', 4),
  ('cp2611_pillow_plaid', 1.2),
  ('cp2611_rug_harvest', 3.003),
  ('cp2611_rack_harvest_hall', 1.25)
  ) as v(id, aspect)
 where h.id = v.id
   and h.art_aspect is distinct from v.aspect;

notify pgrst, 'reload schema';
